<file path="src/customers.js">
import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const CUSTOMERS = JSON.parse(readFileSync(new URL('../data/customers.json', import.meta.url), 'utf8'));

/**
 * All customers: { id, name, email, country, tier }.
 */
export function listCustomers() {
  return CUSTOMERS.map((c) => ({ ...c }));
}

/**
 * One customer by id.
 * @param {string} id
 */
export function getCustomer(id) {
  const c = CUSTOMERS.find((x) => x.id === id);
  return c ? ok({ ...c }) : fail('CUSTOMER_NOT_FOUND');
}

/**
 * Check a customer record before it is stored.
 * @param {{ id?: string, name?: string, email?: string }} c
 */
export function validateCustomer(c) {
  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
  return ok({ ...c });
}
</file>

<file path="src/render.js">
import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const number = invoice.number || 'DRAFT';

  let text = `${number}\n`;
  text += `${customerName}\n`;

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const qtyStr = String(line.qty);
    const nameStr = line.name;
    const priceStr = formatEuros(line.unitPrice);
    const totalStr = formatEuros(total);
    text += `${qtyStr} × ${nameStr} @ ${priceStr} = ${totalStr}\n`;
  }

  const totals = invoiceTotals(invoice);
  text += `Total: ${formatEuros(totals.total)}`;

  return text;
}
</file>
